begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
update public.community_feature_controls set enabled=true where feature='comments';
insert into auth.users(id,email) values('c2380000-0000-4000-8000-000000000001','meal-author@mizyun.test'),('c2380000-0000-4000-8000-000000000002','meal-viewer@mizyun.test'),('c2380000-0000-4000-8000-000000000003','meal-outsider@mizyun.test');
update public.profiles set birth_year=1990 where id::text like 'c2380000%';
insert into public.community_profiles(user_id,handle,display_name,avatar_symbol,status,generation,terms_version,terms_accepted_at,adult_declared_at)
select id,'meal238_'||right(id::text,12),'Synthetic meal member','MM','active',1,'2026-09-30',now(),now() from auth.users where id::text like 'c2380000%';
insert into public.community_relationships(follower_user_id,target_user_id,status) values('c2380000-0000-4000-8000-000000000002','c2380000-0000-4000-8000-000000000001','approved');
insert into public.food_entries(id,user_id,name,consumed_at,calories_kcal,protein_g,carbohydrate_g,fat_g,confirmed_by_user,details) values
('d2380000-0000-4000-8000-000000000001','c2380000-0000-4000-8000-000000000001','Rice bowl',now(),450,20,60,12,true,'{"privateNotes":"private health","provider":"private provider"}'),
('d2380000-0000-4000-8000-000000000002','c2380000-0000-4000-8000-000000000001','Unconfirmed',now(),null,null,null,null,false,'{}');
create temporary table meal_state(id uuid,receipt uuid);
grant all on meal_state to authenticated;
create temporary table meal_snapshots(kind text primary key,value jsonb);
insert into meal_snapshots values('minimal','{"name":"Rice bowl","caloriesKcal":null,"proteinG":null,"carbsG":null,"fatG":null}'),('nutrition','{"name":"Rice bowl","caloriesKcal":450,"proteinG":20,"carbsG":60,"fatG":12}');
grant select on meal_snapshots to authenticated;
select ok(not has_function_privilege('authenticated','public.community_meal_details(uuid,uuid,boolean)','EXECUTE'),'Private meal projection helper cannot bypass source RLS');
select ok(not has_function_privilege('authenticated','public.community_feed_before_meals(integer,timestamp with time zone,uuid)','EXECUTE'),'Raw meal feed reader is inaccessible');
select ok(not has_function_privilege('anon','public.community_publish_meal_activity(uuid,text,integer,uuid,integer,boolean,jsonb)','EXECUTE'),'Anonymous meal publish is denied');
set local role authenticated;
set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c2380000-0000-4000-8000-000000000001';
select throws_ok($$select * from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000002',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000001',0,false,(select value from meal_snapshots where kind='minimal'))$$,'P0001','community_unavailable','Unconfirmed food cannot become an authoritative share');
select throws_ok($$select * from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000001',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000001',0,false,(select value||'{"details":{"privateNotes":"private"}}' from meal_snapshots where kind='minimal'))$$,'P0001','community_conflict','Direct RPC rejects extra private projection fields');
select throws_ok($$select * from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000001',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000001',0,false,(select value||'{"name":"Old name"}' from meal_snapshots where kind='minimal'))$$,'P0001','community_conflict','Stale name confirmation is rejected');
insert into meal_state(id) select id from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000001',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000001',0,false,(select value from meal_snapshots where kind='minimal'));
select is((select meal_details from public.shared_activities where id=(select id from meal_state)),(select value from meal_snapshots where kind='minimal'),'Name-only share omits all nutrition');
select is((select version from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000001',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000001',0,false,(select value from meal_snapshots where kind='minimal'))),1,'Lost publish response returns one durable version');
select is((select count(*) from public.shared_activities),1::bigint,'Retry leaves one card');
select is((select item->>'source_meal_id' from public.community_export_page('activities')),'d2380000-0000-4000-8000-000000000001','Own export retains private source relationship');
select is((select item->'meal_details' from public.community_export_page('activities')),(select value from meal_snapshots where kind='minimal'),'Own export includes deliberate shared projection');
select throws_ok($$select * from public.community_update_activity((select id from meal_state),null,1)$$,'P0001','community_conflict','Generic workout duration edit cannot mutate meals');
select lives_ok($$select public.community_comments('settings',jsonb_build_object('activityId',(select id from meal_state),'enabled',true))$$,'Meal author enables common comment thread');
set local request.jwt.claim.sub='c2380000-0000-4000-8000-000000000002';
select is((select count(*) from public.food_entries),0::bigint,'Follower cannot read source meals under RLS');
select is((select count(*) from public.shared_activities),0::bigint,'Follower cannot read raw source links under RLS');
select is((select source_meal_id from public.community_get_activity((select id from meal_state))),null::uuid,'Recipient card RPC redacts source meal ID');
select is((select meal_details from public.community_feed(20,null,null)),(select value from meal_snapshots where kind='minimal'),'Follower feed has exact allowlisted meal');
select is((select source_meal_id from public.community_feed(20,null,null)),null::uuid,'Follower feed RPC redacts source meal ID');
select is((select source_meal_id from public.community_author_activities('c2380000-0000-4000-8000-000000000001',20,null,null)),null::uuid,'Profile RPC redacts private meal relationship');
select lives_ok($$select public.community_comments('upsert',jsonb_build_object('activityId',(select id from meal_state),'id','b2380000-0000-4000-8000-000000000001','operationId','b2380000-0000-4000-8000-000000000002','expectedVersion',0,'body','Looks good','mentions','[]'::jsonb))$$,'Meal uses common authorized comments');
select lives_ok($$insert into public.community_reactions(activity_id,user_id,reaction) values((select id from meal_state),auth.uid(),'clap')$$,'Meal uses common authorized reactions');
insert into meal_state(receipt) select id from public.community_issue_report_receipt('activity',(select id::text from meal_state where id is not null));
select lives_ok($$select * from public.community_submit_report('activity',(select id::text from meal_state where id is not null),'spam',null,(select receipt from meal_state where receipt is not null))$$,'Meal uses common report receipt safety boundary');
select throws_ok($$select * from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000001',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000003',0,false,(select value from meal_snapshots where kind='minimal'))$$,'P0001','community_unavailable','Cross-owner direct meal publish fails');
set local request.jwt.claim.sub='c2380000-0000-4000-8000-000000000003';
select is((select count(*) from public.community_get_activity((select id from meal_state where id is not null))),0::bigint,'Outsider cannot read shared meal');
set local request.jwt.claim.sub='c2380000-0000-4000-8000-000000000001';
select is((select version from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000001',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000002',1,false,(select value from meal_snapshots where kind='nutrition'))),2,'Explicit nutrition confirmation replaces share');
select is((select source_meal_id from public.community_author_activities('c2380000-0000-4000-8000-000000000001',20,null,null)),null::uuid,'Own profile timeline also omits private source context');
select is((select meal_details from public.shared_activities where id=(select id from meal_state where id is not null)),(select value from meal_snapshots where kind='nutrition'),'Exact opted-in nutrition is stored');
update public.food_entries set details='{"privateNotes":"changed privately"}' where id='d2380000-0000-4000-8000-000000000001';
select is((select version from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000001',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000002',1,false,(select value from meal_snapshots where kind='nutrition'))),2,'Private metadata edit does not change confirmed public projection');
update public.food_entries set protein_g=21 where id='d2380000-0000-4000-8000-000000000001';
select ok((select revoked_at is not null from public.shared_activities where id=(select id from meal_state where id is not null)),'Source nutrition edit revokes historical projection');
select throws_ok($$select * from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000001',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000002',1,false,(select value from meal_snapshots where kind='nutrition'))$$,'P0001','community_conflict','Lost-response retry cannot resurrect revoked meal');
reset role;set local request.jwt.claim.role='service_role';
select ok(exists(select 1 from public.community_revocation_events where user_id='c2380000-0000-4000-8000-000000000001' and kind='activity' and target_id=(select id from meal_state where id is not null)),'Source edits produce health-free activity ledger authority');
select ok(not exists(select 1 from public.community_reports where evidence_snapshot::text like '%private health%' or evidence_snapshot::text like '%private provider%'),'Report evidence never copies private meal metadata');
select ok(exists(select 1 from public.community_reports where evidence_snapshot->'mealDetails'=(select value from meal_snapshots where kind='minimal')),'Report evidence preserves actual seen meal allowlist');
update public.shared_activities set revoked_at=now()-interval '31 days' where id=(select id from meal_state where id is not null);
select * from public.community_retention_batch(500);
select is((select count(*) from public.shared_activities where user_id='c2380000-0000-4000-8000-000000000001'),0::bigint,'Retention removes meal payload and private source link at common deadline');
select is((select payload from public.community_publication_operations where operation_id='a2380000-0000-4000-8000-000000000002'),'{}'::jsonb,'Retention scrubs meal operation confirmation');
update public.community_reports set retention_expires_at=now()-interval '1 day' where subject_user_id='c2380000-0000-4000-8000-000000000001';
select * from public.community_retention_batch(500);
select ok(not exists(select 1 from public.community_reports where subject_user_id='c2380000-0000-4000-8000-000000000001' and evidence_snapshot<>'{}'),'Report retention scrubs the entire meal evidence snapshot');
set local role authenticated;set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c2380000-0000-4000-8000-000000000001';
update public.food_entries set name='Rice bowl',confirmed_by_user=true where id='d2380000-0000-4000-8000-000000000002';
insert into meal_state(id) select id from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000002',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000004',0,false,(select value from meal_snapshots where kind='minimal'));
select lives_ok($$select public.community_unpublish_activity((select id from public.shared_activities where source_meal_id='d2380000-0000-4000-8000-000000000002'),1)$$,'Meal uses common versioned unpublish');
select throws_ok($$select * from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000002',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000004',0,false,(select value from meal_snapshots where kind='minimal'))$$,'P0001','community_conflict','Unpublished meal retry cannot resurrect its card');
select is((select version from public.community_publish_meal_activity('d2380000-0000-4000-8000-000000000002',(now() at time zone 'UTC')::date::text,1,'a2380000-0000-4000-8000-000000000005',1,true,(select value from meal_snapshots where kind='minimal'))),2,'Fresh confirmation can republish revoked meal');
delete from public.food_entries where id='d2380000-0000-4000-8000-000000000002';
select is((select count(*) from public.shared_activities where source_meal_id='d2380000-0000-4000-8000-000000000002'),0::bigint,'Deleting source meal cascades shared payload deletion');
select * from finish();
rollback;
